+		return FilterPropagateResult::NO_PRUNING_POSSIBLE;
+	}
+	if (lower_res == FilterPropagateResult::FILTER_ALWAYS_FALSE ||
+	    upper_res == FilterPropagateResult::FILTER_ALWAYS_FALSE) {
