[editor/scene/2d/tiles/tile_atlas_view.cpp:335](https://github.com/godotengine/godot/blob/master/modules/tilemap/editor/tile_atlas_view.cpp#L333):

```cpp
void TileAtlasView::_draw_base_tiles_texture_grid() {
	if (tile_set_atlas_source.is_null()) {
		return;
	}
	Ref<Texture2D> texture = tile_set_atlas_source->get_texture();
	if (texture.is_valid()) {
		Vector2i margins = tile_set_atlas_source->get_margins();
		Vector2i separation = tile_set_atlas_source->get_separation();
		Vector2i texture_region_size = tile_set_atlas_source->get_texture_region_size();

		Size2i grid_size = tile_set_atlas_source->get_atlas_grid_size();

		for (int x = 0; x < grid_size.x; x++) {
			for (int y = 0; y < grid_size.y; y++) {
				Vector2i origin = margins + (Vector2i(x, y) * (texture_region_size + separation));
				Vector2i base_tile_coords = tile_set_atlas_source->get_tile_at_coords(Vector2i(x, y));
				if (base_tile_coords != TileSetSource::INVALID_ATLAS_COORDS) {
					if (base_tile_coords == Vector2i(x, y)) {
						// Draw existing tile.
						Vector2i size_in_atlas = tile_set_atlas_source->get_tile_size_in_atlas(base_tile_coords);
						Vector2 region_size = texture_region_size * size_in_atlas + separation * (size_in_atlas - Vector2i(1, 1));
						base_tiles_texture_grid->draw_rect(Rect2i(origin, region_size), Color(1.0, 1.0, 1.0, 0.8), false);
					}
				} else {
					// Draw the grid.
					base_tiles_texture_grid->draw_rect(Rect2i(origin, texture_region_size), Color(0.7, 0.7, 0.7, 0.1), false);
				}
			}
		}
	}
```

The number of times we call `draw_rect` in the inner nested for loop scales exponentially with linearly decreasing tile size. For your 900x600 image example with `texture_region_size` as 1x1 that's 900x600 = 540,000 calls to `draw_rect` since every pixel is technically a tile. For 16x16 it's (900x600) / (1/16^2) ~ 2100 calls.

Basically becomes a crappy software renderer, lol. To make sure I ran this through a profiler. See in the flame graph that `_draw_base_tiles_texture_grid` is what ends up eating most time:

When texture_region_size is 16x16:

<img width="3456" height="1758" alt="Image" src="https://github.com/user-attachments/assets/69df6d3d-8734-4ba1-8da0-e3a4762bd53c" />

When it is 3x3:

<img width="3456" height="1724" alt="Image" src="https://github.com/user-attachments/assets/ec9ff5cc-5316-42c1-8ebb-25a352c4b653" />

Couldn't get it for 1x1 since my editor would just crash and hence my profiling tool would dump half-written corrupt data. Anyways, pretty sure this is it. Both sample screenshots above are for a 1s interval when I was on the TileSet menu looking at the grid.

If you change the function to batch the squares (lines in this case) and only issue one draw call at the end, FPS goes up dramatically: 

```cpp
void TileAtlasView::_draw_base_tiles_texture_grid() {
	if (tile_set_atlas_source.is_null()) {
		return;
	}
	Ref<Texture2D> texture = tile_set_atlas_source->get_texture();
	if (texture.is_valid()) {
		Vector2i margins = tile_set_atlas_source->get_margins();
		Vector2i separation = tile_set_atlas_source->get_separation();
		Vector2i texture_region_size = tile_set_atlas_source->get_texture_region_size();

		Size2i grid_size = tile_set_atlas_source->get_atlas_grid_size();

		int num_squares_h = texture->get_height() / texture_region_size.height;
		int num_squares_w = texture->get_width() / texture_region_size.width;

		// Square 8 pts (4 lines 2 pts e/a)
		Vector<Point2> points;
		points.reserve(num_squares_h * num_squares_w * 8);

		Vector<Color> colors;
		colors.reserve(num_squares_h * num_squares_w * 8);

		for (int x = 0; x < grid_size.x; x++) {
			for (int y = 0; y < grid_size.y; y++) {
				Vector2i origin = margins + (Vector2i(x, y) * (texture_region_size + separation));
				Vector2i base_tile_coords = tile_set_atlas_source->get_tile_at_coords(Vector2i(x, y));
				Vector2i region_size;
				Color tile_color;

				if (base_tile_coords != TileSetSource::INVALID_ATLAS_COORDS) {
					if (base_tile_coords == Vector2(x, y)) {
						tile_color = Color(1.0, 1.0, 1.0, 0.8);

						Vector2i size_in_atlas = tile_set_atlas_source->get_tile_size_in_atlas(base_tile_coords);
						region_size = texture_region_size * size_in_atlas + separation * (size_in_atlas - Vector2i(1, 1));
					}
				} else {
					tile_color = Color(0.7, 0.7, 0.7, 0.1);
					region_size = texture_region_size;
				}

				for (int c = 0; c < 4; c++) {
					colors.push_back(tile_color);
				}

				Vector2i top_line_left = origin;
				Vector2i top_line_right = top_line_left + Vector2i{ region_size.x, 0 };

				Vector2i bottom_line_left = origin + Vector2i{ 0, region_size.y };
				Vector2i bottom_line_right = bottom_line_left + Vector2i{ region_size.x, 0 };

				Vector2i left_line_top = origin;
				Vector2i left_line_bottom = left_line_top + Vector2i{ 0, region_size.y };

				Vector2i right_line_top = origin + Vector2i{ region_size.x, 0 };
				Vector2i right_line_bottom = right_line_top + Vector2i{ 0, region_size.y };

				points.push_back(top_line_left);
				points.push_back(top_line_right);
				points.push_back(bottom_line_left);
				points.push_back(bottom_line_right);
				points.push_back(left_line_top);
				points.push_back(left_line_bottom);
				points.push_back(right_line_top);
				points.push_back(right_line_bottom);
			}
		}

		if (!points.is_empty()) {
			RenderingServer::get_singleton()->canvas_item_add_multiline(
					base_tiles_texture_grid->get_canvas_item(),
					points,
					colors);
		}
	}
}
```

At 1x1 the editor now just lags instead of freezing (by eye maybe ~10fps). At 3x3 it feels like ~60 fps. I do notice that tile selection is still slow, though (as in, when you move your cursor over a tile and it gets highlighted, the rendered frame lags behind the mouse a bit when your tile region is small)

